// Normalise the form into the settings every later step reads.
const form = $input.first().json;
const question = String(form.question || '').trim();
const depth = String(form.depth || 'Standard');
const subQuestionCount = depth.startsWith('Quick') ? 3 : depth.startsWith('Thorough') ? 5 : 4;
return [{ json: { question, depth, subQuestionCount, today: $now.toFormat('yyyy-MM-dd') } }];

// The planner decides what to search for; this decides how many searches run.
// Each search is one request to DuckDuckGo, which blocks an IP after roughly
// fifteen in a few minutes, so the count comes from the form, never the model.
const settings = $('Research settings').first().json;
const output = $input.first().json.output || {};
const planned = Array.isArray(output.sub_questions) ? output.sub_questions : [];
const seen = new Set();
const items = [];
for (const p of planned) {
  const question = String((p && p.question) || '').trim();
  const query = String((p && p.search_query) || question)
    .replace(/["']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 120);
  const key = query.toLowerCase();
  if (!question || !query || seen.has(key)) continue;
  seen.add(key);
  items.push({ json: { index: items.length + 1, question, search_query: query } });
  if (items.length >= settings.subQuestionCount) break;
}
if (items.length === 0) {
  items.push({ json: { index: 1, question: settings.question, search_query: settings.question.slice(0, 120) } });
}
return items;

// Always returns exactly one item for the sub-question, whatever the search
// did. A sub-question that silently vanished here would vanish from the
// report too, and the report would read as complete.
const sub = $('Loop over sub-questions').first().json;
const results = $input.all().map((i) => i.json);

const failure = results.find((r) => r.error);
const blocked = !!failure && /challenge|bot-detection|back-off|not sent|rate.?limit|too many requests|access denied|unusual search|status code (403|429)/i.test(String(failure.error));

// Text that is a page's furniture rather than its content: consent walls,
// "enable JavaScript" shells, paywall teasers. It passes a length check, so it
// is caught by what it says.
const WALL = /enable javascript|accept (all )?cookies|cookie (policy|settings|consent)|subscribe to (continue|read)|access denied|are you a robot|verify you are (a )?human/i;

const sources = [];
for (const r of results) {
  if (!r.url || r.error) continue;
  const content = typeof r.pageContent === 'string' ? r.pageContent.trim() : '';
  const garbled = (content.match(/�/g) || []).length > content.length * 0.01;
  const isPage = !r.pageContentError && content.length >= 400 && !garbled && !WALL.test(content.slice(0, 800));
  // The Code node's sandbox has no URL class, so the host is read directly.
  const hostMatch = /^https?:\/\/([^\/?#:]+)/i.exec(String(r.url));
  if (!hostMatch) continue;
  const host = hostMatch[1].toLowerCase().replace(/^www\./, '');
  const text = isPage ? content : String(r.description || '').trim();
  if (text.length < 80) continue;
  sources.push({
    title: String(r.pageTitle || r.title || host).slice(0, 200),
    url: r.url,
    host,
    published: r.pagePublished || null,
    kind: isPage ? 'page' : 'snippet',
    text,
  });
}

const pages = sources.filter((s) => s.kind === 'page');
const pageHosts = new Set(pages.map((s) => s.host));
let status = 'no_evidence';
if (blocked) status = 'blocked';
else if (pages.length >= 2 && pageHosts.size >= 2) status = 'ok';
else if (sources.length > 0) status = 'thin';

return [{
  json: {
    index: sub.index,
    subQuestion: sub.question,
    searchQuery: sub.search_query,
    status,
    error: failure ? String(failure.error) : null,
    sources,
  },
}];

// Sources are numbered here, in code, so the model can only ever cite an id
// that exists; it never writes a URL. The same page found by two
// sub-questions is one source.
const graded = $input.all().map((i) => i.json).sort((a, b) => a.index - b.index);
const settings = $('Research settings').first().json;

// Read with a pattern because the Code node's sandbox has no URL class.
const canonical = (url) => {
  const m = /^https?:\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?/i.exec(String(url));
  if (!m) return String(url).toLowerCase();
  return (m[1].replace(/^www\./i, '') + m[2].replace(/\/+$/, '') + (m[3] || '')).toLowerCase();
};

const byKey = new Map();
const sources = [];
const subQuestions = graded.map((g) => {
  const ids = [];
  for (const s of g.sources) {
    const key = canonical(s.url);
    let source = byKey.get(key);
    if (!source) {
      source = Object.assign({ id: 'S' + (sources.length + 1) }, s);
      byKey.set(key, source);
      sources.push(source);
    }
    if (!ids.includes(source.id)) ids.push(source.id);
  }
  return { index: g.index, question: g.subQuestion, status: g.status, error: g.error, sourceIds: ids };
});

const okCount = subQuestions.filter((s) => s.status === 'ok').length;
const blockedCount = subQuestions.filter((s) => s.status === 'blocked').length;
const blocked = blockedCount > 0;
// Only stop here when there is nothing to work with. Whether what was read
// answers the question is decided after extraction, by the verified findings:
// many research pages refuse to be fetched, and their search snippets still
// carry quotable facts.
const enough = sources.length >= 3 && blockedCount * 2 < subQuestions.length;

// Page text is untrusted: any of it may be written to steer a model. Each
// source is fenced with a marker that includes a per-run nonce, so a page
// cannot forge the end of its own fence.
const nonce = Math.random().toString(36).slice(2, 10);
const evidence = sources.map((s) => [
  '<<<SOURCE ' + s.id + ' ' + nonce + '>>>',
  'Title: ' + s.title,
  'Site: ' + s.host + (s.published ? ' (published ' + s.published + ')' : ''),
  'Kind: ' + (s.kind === 'page' ? 'full page text' : 'search snippet only'),
  'Text:',
  s.text,
  '<<<END ' + s.id + ' ' + nonce + '>>>',
].join('\n')).join('\n\n');

const plan = subQuestions.map((s) => s.index + '. ' + s.question +
  (s.sourceIds.length ? '  [sources: ' + s.sourceIds.join(', ') + ']' : '  [no sources found]')).join('\n');

return [{
  json: {
    question: settings.question,
    today: settings.today,
    nonce,
    enough,
    blocked,
    okCount,
    subQuestions,
    sources,
    plan,
    evidence,
  },
}];

// A finding survives only if its quote really is in the source it names. This
// is what keeps the report tied to what was read rather than to what the
// model remembers.
const bundle = $('Number the sources').first().json;
const output = $input.first().json.output || {};
const findings = Array.isArray(output.findings) ? output.findings : [];

const normalise = (s) => String(s || '')
  .toLowerCase()
  .replace(/[‘’‛]/g, "'")
  .replace(/[“”‟]/g, '"')
  .replace(/[–—]/g, '-')
  .replace(/…/g, '')
  .replace(/\.\.\.$/, '')
  .replace(/\s+/g, ' ')
  .trim();

const byId = new Map(bundle.sources.map((s) => [s.id, s]));
const indexes = new Set(bundle.subQuestions.map((s) => s.index));
const verified = [];
let discarded = 0;

for (const f of findings) {
  // The model sometimes writes the id as "S1 k3j9x2" (the marker's per-run code), "[S1]" or "Source 1".
  const idMatch = String((f && f.source_id) || '').trim().match(/^\W*(?:source\s*)?s?\s*0*([0-9]+)/i);
  const source = idMatch ? byId.get('S' + idMatch[1]) : undefined;
  const quote = normalise(f && f.quote);
  const ok = source && quote.length >= 20 && indexes.has(Number(f.sub_question)) &&
    normalise(source.text).includes(quote);
  if (!ok) { discarded += 1; continue; }
  // The prompt asks for at most six per sub-question; enforced here, where it
  // cannot make the output parser reject the whole answer.
  if (verified.filter((v) => v.subQuestion === Number(f.sub_question)).length >= 6) continue;
  verified.push({
    sourceId: source.id,
    subQuestion: Number(f.sub_question),
    claim: String(f.claim || '').trim().slice(0, 500),
    quote: String(f.quote).trim().slice(0, 400),
  });
}

const lines = bundle.subQuestions.map((s) => {
  const mine = verified.filter((v) => v.subQuestion === s.index);
  const header = '### ' + s.index + '. ' + s.question + ' (' + s.sourceIds.length + ' sources read' +
    (s.status === 'blocked' ? ', search blocked' : '') + ')';
  if (mine.length === 0) return header + '\n- No verified finding: the sources read did not support an answer.';
  return header + '\n' + mine.map((v) => '- [' + v.sourceId + '] ' + v.claim + ' (quote: "' + v.quote + '")').join('\n');
}).join('\n\n');

// Two verified findings is the least a report can rest on; below that the
// writer would be filling the page from memory.
const enough = verified.length >= 2;

return [{ json: { verified, discarded, verifiedCount: verified.length, enough, findingsForWriter: lines } }];

