// The model wrote prose with [S#] markers. Everything a reader can click, and
// every claim about coverage, is added here from data, not taken from the model.
const bundle = $('Number the sources').first().json;
const checks = $('Verify the quotes').first().json;
let body = String($input.first().json.text || '');

// The model's output is text, and it stays text: tags, images and links are
// removed before it is rendered, whatever a source may have told it to write.
// A link target may hold one level of parentheses, as in javascript:alert(1).
body = body
  .replace(/```[a-z]*\n?|```/gi, '')
  .replace(/<(script|style)\b[\s\S]*?<\/\1\s*>/gi, '')
  .replace(/<\/?[a-z!][^<>]*>/gi, '')
  // An unclosed tag would otherwise swallow text up to the next '>'.
  .replace(/<\/?[a-z!][^<>\n]*$/gim, '')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/!\[[^\]]*\]\((?:[^()]|\([^()]*\))*\)/g, '')
  .replace(/\[([^\]]+)\]\((?:[^()]|\([^()]*\))*\)/g, '$1')
  // Reference-style links need a definition line to become links; without
  // one, [text][ref] stays plain text. Bare addresses would be auto-linked.
  .replace(/^ {0,3}\[[^\]\n]+\]:.*$/gm, '')
  .replace(/\[([^\]\n]+)\]\[(?!S\d)[^\]\n]*\]/g, '$1')
  .replace(/\b(?:https?|ftp):\/\/\S+|\bwww\.\S+/gi, '')
  // The report's title is the question, added below; a title the model wrote
  // would be a second one.
  .replace(/^#\s.*$/gm, '');

// Only a source with a verified finding may be cited: the writer saw nothing
// else, so any other id - even one of a source that was read - is invented.
const known = new Set(checks.verified.map((v) => v.sourceId));
const used = [];
let dropped = 0;
body = body.replace(/([ \t]*)\[(S\d+(?:\s*,\s*S\d+)*)\]/g, (match, lead, list) => {
  const all = list.split(/\s*,\s*/);
  const ids = all.filter((id) => known.has(id));
  dropped += all.length - ids.length;
  ids.forEach((id) => { if (!used.includes(id)) used.push(id); });
  return ids.length ? lead + '[' + ids.join(', ') + ']' : '';
});

// The report promises that every claim cites its source, so a sentence left
// without a citation is not shown. Headings and the Gaps section, which says
// what could not be found, are exempt.
let uncited = 0;
body = body.split(/^(?=## )/m).map((section) => {
  if (/^## Gaps and limits/i.test(section)) return section;
  return section.split('\n').map((line) => {
    if (!line.trim() || /^\s*(#|\|)/.test(line)) return line;
    const marker = (line.match(/^\s*(?:[-*+]|\d+\.)\s+/) || [''])[0];
    const sentences = line.slice(marker.length).split(/(?<=[.!?])\s+(?=[A-Z0-9"'(])/);
    const kept = sentences.filter((s) => {
      if (/\[S\d+/.test(s)) return true;
      if (s.trim()) uncited += 1;
      return false;
    });
    return kept.length ? marker + kept.join(' ') : '';
  }).join('\n');
}).join('').replace(/\n{3,}/g, '\n\n');

const escapeMd = (s) => String(s).replace(/[\\`*_{}\[\]()#+!|<>]/g, (c) => '\\' + c);
const safeUrl = (u) => (/^https?:\/\//i.test(u) ? u.replace(/[()\s]/g, encodeURIComponent) : null);

const references = bundle.sources
  .filter((s) => used.includes(s.id))
  .map((s) => {
    const url = safeUrl(s.url);
    const title = escapeMd(s.title);
    // Pages give dates as timestamps as often as not; the day is what a reader needs.
    const published = s.published && /^\d{4}-\d{2}-\d{2}T/.test(s.published) ? s.published.slice(0, 10) : s.published;
    const where = escapeMd(s.host) + (published ? ', ' + escapeMd(published) : '') +
      (s.kind === 'snippet' ? ' (search snippet only)' : '');
    return '- **' + s.id + '** ' + (url ? '[' + title + '](' + url + ')' : title) + ' - ' + where;
  });

// Counts, not verdicts: a readable page is not necessarily a relevant one, and
// the findings column shows what the report could actually use.
const kindOf = new Map(bundle.sources.map((s) => [s.id, s.kind]));
const coverage = [
  '| # | Sub-question | Read | Findings used |',
  '|---|---|---|---|',
].concat(bundle.subQuestions.map((s) => {
  const pages = s.sourceIds.filter((id) => kindOf.get(id) === 'page').length;
  const snippets = s.sourceIds.length - pages;
  const read = s.status === 'blocked' ? 'Blocked by DuckDuckGo'
    : s.sourceIds.length === 0 ? 'Nothing usable'
      : pages + (pages === 1 ? ' page' : ' pages') + (snippets ? ' + ' + snippets + (snippets === 1 ? ' snippet' : ' snippets') : '');
  const findings = checks.verified.filter((v) => v.subQuestion === s.index).length;
  return '| ' + s.index + ' | ' + escapeMd(s.question) + ' | ' + read + ' | ' + findings + ' |';
}));

const header = '*Researched ' + bundle.today + ' from ' + bundle.sources.length + ' sources found with DuckDuckGo. ' +
  checks.verifiedCount + ' quoted findings verified against the sources' +
  (checks.discarded ? ', ' + checks.discarded + ' discarded because their quote was not in the source' : '') +
  (dropped ? ', ' + dropped + ' citations to unknown sources removed' : '') +
  (uncited ? ', ' + uncited + (uncited === 1 ? ' sentence' : ' sentences') + ' without a citation left out' : '') + '.*';

const report = [
  '# ' + escapeMd(bundle.question),
  header,
  body.trim(),
  '## Evidence coverage',
  coverage.join('\n'),
  '## Sources',
  references.length ? references.join('\n') : '_No source was cited._',
].join('\n\n');

return [{ json: { report, citedSources: used.length, droppedCitations: dropped } }];

// Too little was found to write a report that would be more than the model's
// memory. Say what happened instead of writing one. Two paths lead here: too
// few readable sources, or sources that held no quotable answer.
const bundle = $('Number the sources').first().json;
const input = $input.first().json;
const noFindings = 'verifiedCount' in input;
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const label = { ok: 'readable pages found', thin: 'little readable', no_evidence: 'nothing usable found', blocked: 'blocked by DuckDuckGo' };
const rows = bundle.subQuestions.map((s) => '<li>' + esc(s.question) + ' <em>(' + label[s.status] + ')</em></li>').join('');
const summary = noFindings
  ? 'The pages that were read did not contain quotable facts that answer the question: ' + input.verifiedCount +
    ' finding' + (input.verifiedCount === 1 ? '' : 's') + ' checked out against its source, so no report was written.'
  : bundle.blocked && bundle.sources.length >= 3
    ? 'DuckDuckGo blocked half or more of the searches, so no report was written.'
    : 'Only ' + bundle.sources.length + ' usable source' + (bundle.sources.length === 1 ? ' was' : 's were') + ' found, so no report was written.';
const advice = bundle.blocked
  ? 'DuckDuckGo stopped answering this server for a while - it limits how many searches one IP address can make. Wait about 30 minutes before trying again, and avoid running other DuckDuckGo workflows meanwhile.'
  : 'Try rephrasing the question more specifically, or choose a different depth.';
const html = '<h2>No report this time</h2>' +
  '<p>' + esc(summary) + ' A report built on so little would mostly be the model&#39;s memory, dressed up with citations.</p>' +
  '<ul>' + rows + '</ul><p>' + esc(advice) + '</p>';
return [{ json: { html } }];
